function toast(te,en){let t=document.getElementById('mdtoast');if(!t){t=document.createElement('div');t.id='mdtoast';document.body.appendChild(t)}t.innerHTML=E(TE()?te:en)+'<div class="p2">'+E(TE()?en:te)+'</div>';t.style.display='block';clearTimeout(toastT);toastT=setTimeout(()=>{t.style.display='none'},2600)}
const SAFE=[["ఇది విద్య మరియు ఆరోగ్య అవగాహన కోసం మాత్రమే, ఏ వైద్య లేదా మానసిక వ్యాధికి చికిత్స కాదు.","Educational and wellness use only. It is not a treatment for any medical or psychiatric condition."],["దయచేసి అర్హత కలిగిన తల్లిదండ్రులు, ఉపాధ్యాయులు, కౌన్సెలర్ లేదా ఆరోగ్య నిపుణులతో మాట్లాడండి.","Please speak with a qualified parent, teacher, counselor or healthcare professional."]];
const foot=()=>`<div class="foot">${E(P(SAFE[0]))}<br>${E(P(SAFE[1]))}</div>`;
const care=()=>`<div class="c warn"><b>💛 ${E(P(['తీవ్రమైన విషయాలకు','For serious concerns']))}</b><div class="p1">${E(P(SAFE[1]))}</div><div class="p2">${E(TE()?SAFE[1][1]:SAFE[1][0])}</div></div>`;
function hdr(title){const t=title?`<div style="flex:1;min-width:0;font-weight:700;font-size:15px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${E(title)}</div>`:'<div style="flex:1"></div>';return `<div class="top"><button class="b g sm" data-a="back" aria-label="Back">← ${TE()?'వెనుకకు':'Back'}</button><button class="b g sm" data-a="home" aria-label="Home">🏠</button>${t}<button class="b g sm" data-a="lang" aria-label="Language">${TE()?'EN':'తె'}</button><button class="b g sm" data-a="close" aria-label="Close">✕</button></div><div class="pg" title="${overall()}%"><i style="width:${overall()}%"></i></div>`}
function go(s,a){stk.push({s,a});try{history.pushState({md:stk.length-1},'','#meditation')}catch(e){}draw(true)}
function back(){if(stk.length>1)history.back();else close()}
function homeNav(){if(stk.length>1)history.go(-(stk.length-1));else draw(true)}
function onPop(e){if(!ov)return;const s=e.state;if(s&&typeof s.md==='number'){stk.length=Math.min(stk.length,s.md+1);draw(true)}else close(true)}
function render(h,keep){const top=keep?ov.scrollTop:0;ov.innerHTML='<div class="w">'+h+'</div>';ov.scrollTop=top}
function draw(reset){if(!ov)return;const c=cur();if(c.s!=='player')stopPl();if(c.s!=='quiz')qz=qz&&c.s==='qres'?qz:null;const keep=!reset;
 ({home:scHome,course:scCourse,lesson:scLesson,player:scPlayer,quiz:scQuiz,qres:scQres,progress:scProg,challenge:scCh,mindmap:scMap,infos:scInfos,books:scBooks,safety:scSafety})[c.s](c.a,keep)}
const nextMod=()=>{let i=MODS.findIndex(m=>!D.done[m.id]);return i<0?0:i};
const todayMod=()=>{const dn=D.ch.indexOf(today())>=0;const k=Math.min(D.ch.length,20);const i=PLAN[dn?Math.min(D.ch.length,20):k]-1;const j=Math.max(0,Math.min(19,i||0));return unlocked(j)?j:nextMod()};
function ring(p,sz,col){const r=sz/2-6,c=2*Math.PI*r;return `<svg width="${sz}" height="${sz}" viewBox="0 0 ${sz} ${sz}"><circle cx="${sz/2}" cy="${sz/2}" r="${r}" fill="none" stroke="#ffffff22" stroke-width="7"/><circle cx="${sz/2}" cy="${sz/2}" r="${r}" fill="none" stroke="${col||'#22d3ee'}" stroke-width="7" stroke-linecap="round" stroke-dasharray="${c}" stroke-dashoffset="${c*(1-Math.min(1,p))}" transform="rotate(-90 ${sz/2} ${sz/2})"/></svg>`}
function scHome(){const dn=dailyMin()/DAILY_GOAL,tm=MODS[todayMod()],nm=MODS[nextMod()];
 let h=hdr('')+`<h2>🧘 ${E(TE()?'మైండ్ పవర్ మెడిటేషన్‌కు స్వాగతం':'Welcome to Mind Power Meditation')}</h2><div class="p2" style="margin-top:-2px">${E(TE()?'Welcome to Mind Power Meditation':'మైండ్ పవర్ మెడిటేషన్‌కు స్వాగతం')}</div><div class="p1" style="color:#22d3ee;font-weight:700">${E(P(['ఏకాగ్రత • ప్రశాంతత • జ్ఞాపకశక్తి • ఆత్మవిశ్వాసం • భావోద్వేగ సమతుల్యత','Focus • Calm • Memory • Confidence • Emotional Balance']))}</div><div class="p2">${E(TE()?'Focus • Calm • Memory • Confidence • Emotional Balance':'ఏకాగ్రత • ప్రశాంతత • జ్ఞాపకశక్తి • ఆత్మవిశ్వాసం • భావోద్వేగ సమతుల్యత')}</div>`;
 h+=`<div class="grid3"><div class="st"><b>🔥 ${D.streak}</b><span>${W('వరుస రోజులు','Streak').replace(/<[^>]+>/g,' ')}</span></div><div class="st"><b>⏱ ${Math.round(D.mins*10)/10}</b><span>${E(P(['ధ్యాన నిమిషాలు','Minutes']))}</span></div><div class="st"><b>📘 ${doneCount()}/20</b><span>${E(P(['పూర్తి పాఠాలు','Lessons done']))}</span></div><div class="st"><b>⭐ ${level()}</b><span>${E(P(['స్థాయి','Level']))} · ${D.xp} XP</span></div><div class="st"><b>🎯 ${dailyMin()}/${DAILY_GOAL}</b><span>${E(P(['నేటి లక్ష్యం (ని)','Daily goal (min)']))}</span></div><div class="st"><b>📈 ${overall()}%</b><span>${E(P(['పురోగతి','Progress']))}</span></div></div>`;
 h+=`<div class="c"><h3>🌤 ${E(P(['నేటి ధ్యానం','Today\u2019s meditation']))}</h3><div class="row"><div style="flex:1;min-width:0">${B(tm.n,1)}<div class="sm">⏱ ${tm.min} ${TE()?'నిమి':'min'} · ${E(P(DIFF[tm.df]))}</div></div><div>${ring(dn,64,dn>=1?'#22c55e':'#22d3ee')}</div></div><div class="row"><button class="b ok" data-a="play" data-v="${tm.no-1}">▶ ${E(P(['ఈ రోజు ధ్యానం మొదలుపెట్టు','Start Today\u2019s Meditation']))}</button><button class="b" data-a="lesson" data-v="${nm.no-1}">📖 ${E(P(['కోర్సు కొనసాగించు','Continue Course']))}: ${nm.no}</button></div></div>`;
 h+=`<div class="grid2"><button class="b big4" data-a="play" data-v="${tm.no-1}"><span style="font-size:26px">🌅</span>${B(['ఈ రోజు ధ్యానం మొదలుపెట్టు','Start Today\u2019s Meditation'])}</button><button class="b big4" data-a="lesson" data-v="${nm.no-1}"><span style="font-size:26px">📚</span>${B(['నేర్చుకోవడం కొనసాగించు','Continue Learning'])}</button><button class="b big4" data-a="challenge"><span style="font-size:26px">🏆</span>${B(['21 రోజుల ఛాలెంజ్','21-Day Challenge'])}<span class="sm">${D.ch.length}/21</span></button><button class="b big4" data-a="progress"><span style="font-size:26px">📊</span>${B(['నా పురోగతి','My Progress'])}</button></div>`;
 h+=`<div class="c"><h3>${E(P(['అన్ని విభాగాలు','Explore']))}</h3><div class="row"><button class="b g" data-a="course">🗺 ${E(P(['20 పాఠాల కోర్సు','20-Module Course']))}</button><button class="b g" data-a="mindmap">🧩 ${E(P(['మైండ్ మ్యాప్','Mind Map']))}</button><button class="b g" data-a="infos">🖼 ${E(P(['ఇన్ఫోగ్రాఫిక్స్','Infographics']))}</button><button class="b g" data-a="books">📚 ${E(P(['చదవాల్సిన పుస్తకాలు','Books to Read']))}</button><button class="b g" data-a="safety">💛 ${E(P(['భద్రత','Safety']))}</button></div></div>`;
 h+=care()+foot();render(h)}
function scCourse(a,keep){let h=hdr(P(['కోర్సు','Course']))+`<h2>🗺 ${E(P(['20 పాఠాల అభ్యాస మార్గం','20-Module Learning Path']))}</h2><div class="p2">${E(TE()?'20-Module Learning Path':'20 పాఠాల అభ్యాస మార్గం')}</div><div class="path">`;const nx=nextMod();
 MODS.forEach((m,i)=>{const lk=!unlocked(i),dn=!!D.done[m.id];h+=`<div class="node ${dn?'dn':i===nx&&!lk?'cu':''}" data-n="${m.no}"><button class="card ${lk?'lock':''} ${dn?'dn':''}" data-a="${lk?'locked':'lesson'}" data-v="${i}"><span class="ic">${lk?'🔒':m.ic}</span><span style="flex:1;min-width:0">${B(m.n)}<div class="bar" style="margin-top:4px"><i style="width:${modPct(m)}%"></i></div><div class="sm">⏱ ${m.min} ${TE()?'నిమి':'min'} · ${E(P(DIFF[m.df]))} · ${modPct(m)}%</div></span><span>${lk?'':dn?'✅':'▶'}</span></button></div>`});
 render(h+'</div>'+foot(),keep)}
function scLesson(i,keep){const m=MODS[i];if(!unlocked(i)){toast('ఈ పాఠం ఇంకా లాక్ అయింది','This lesson is still locked');return}
 const dg=m.dg&&DG[m.dg]?`<div class="c">${DG[m.dg]()}</div>`:'';const list=(a)=>'<ul>'+a.map(x=>`<li>${B(x)}</li>`).join('')+'</ul>';
 let h=hdr(P(m.n))+`<div class="row"><span style="font-size:34px">${m.ic}</span><div style="flex:1">${B(m.n,1)}</div></div><div><span class="chip">#${m.no}/20</span><span class="chip">⏱ ${m.min} ${TE()?'నిమి':'min'}</span><span class="chip">${E(P(DIFF[m.df]))} · ${E(TE()?DIFF[m.df][1]:DIFF[m.df][0])}</span></div>`;
 h+=`<div class="c"><h3>${E(P(['పరిచయం','Intro']))}</h3>${B(m.i)}<h3>🎯 ${E(P(['నేర్చుకునే లక్ష్యం','Learning objective']))}</h3>${B(m.o)}</div>`;
 h+=`<div class="c"><h3>💡 ${E(P(['సులభమైన వివరణ','Simple explanation']))}</h3>${B(m.x)}<button class="b g sm" data-a="listen" data-v="${i}">🔊 ${E(P(['వినండి','Listen']))}</button></div>`+dg;
 h+=`<div class="c"><h3>🔑 ${E(P(['ముఖ్య పదాలు, ఉచ్చారణ','Key terms and pronunciation']))}</h3>`+m.k.map(k=>`<div class="row" style="justify-content:space-between"><div><b>${E(k[0])}</b> - ${E(k[1])}<div class="p2">${E(P(['ఉచ్చారణ','Say it'])+': '+k[2])}</div></div><button class="b g sm" data-a="say" data-v="${E(k[0])}">🔊</button></div>`).join('')+'</div>';
 h+=`<div class="c"><h3>🪜 ${E(P(['దశలవారీ సూచనలు','Step-by-step']))}</h3><ol>`+m.st.map(s=>`<li>${B(s)}</li>`).join('')+`</ol></div>`;
 h+=`<div class="c"><h3>✨ ${E(P(['ప్రయోజనాలు','Benefits']))}</h3>${list(m.b)}</div><div class="dd"><div class="c" style="border-color:#22c55e88"><h3 style="color:#86efac">✅ ${E(P(['చేయవలసినవి','Do']))}</h3>${list(m.d)}</div><div class="c" style="border-color:#fb923c88"><h3 style="color:#fdba74">⚠️ ${E(P(['చేయకూడనివి','Don\u2019t']))}</h3>${list(m.nd)}</div></div>`;
 h+=`<div class="c"><h3>🎮 ${E(P(['ఇంటరాక్టివ్ కార్యకలాపం','Interactive activity']))}</h3>${B(m.a)}<button class="b ${D.act[m.id]?'ok':'g'}" data-a="act" data-v="${i}">${D.act[m.id]?'✅':'☐'} ${E(P(['నేను ప్రయత్నించాను','I tried it']))}</button><h3>📝 ${E(P(['అభ్యాస పని','Practice task']))}</h3>${B(m.p)}</div>`;
 h+=`<div class="c"><h3>📈 ${E(P(['ఈ పాఠం పురోగతి','Lesson progress']))}</h3><div class="bar"><i style="width:${modPct(m)}%"></i></div><div class="sm">${D.done[m.id]?'✅':'⬜'} ${E(P(['సెషన్','Session']))} · ${D.act[m.id]?'✅':'⬜'} ${E(P(['కార్యకలాపం','Activity']))} · ${D.quiz[m.id]!=null?'✅':'⬜'} ${E(P(['క్విజ్','Quiz']))} · ${modPct(m)}%</div></div>`;
 if(m.care)h+=care();
 h+=`<div class="row"><button class="b ok" data-a="play" data-v="${i}">▶ ${E(P(['ధ్యానం మొదలుపెట్టు','Start Meditation']))}</button><button class="b" data-a="listen" data-v="${i}">🔊 ${E(P(['వినండి','Listen']))}</button><button class="b g" data-a="quiz" data-v="${i}">❓ ${E(P(['క్విజ్','Quiz']))}</button>${i<19?`<button class="b or" data-a="lesson" data-v="${i+1}">${E(P(['తరువాత పాఠం','Next Lesson']))} →</button>`:''}</div>`+foot();render(h,keep)}
