function stopPl(clr){if(pl){clearInterval(pl.tm);pl.tm=null;pl.run=false}try{speechSynthesis.cancel()}catch(e){}bgStop();if(clr)pl=null}
function segAt(m,t){let a=0;for(let k=0;k<m.seg.length;k++){a+=m.seg[k][2];if(t<a)return k}return m.seg.length-1}
const mmss=s=>pad(Math.floor(s/60))+':'+pad(Math.floor(s%60));
function scPlayer(i,keep){const m=MODS[i];if(!pl||pl.i!==i){stopPl();pl={i,t:0,run:false,seg:-1,fin:null}}
 const sel=(k,opts)=>'<div class="sel">'+opts.map(o=>`<button class="b g ${D[k]===o[0]?'on':''}" data-a="set" data-k="${k}" data-v="${o[0]}">${E(P(o[1]))}</button>`).join('')+'</div>';
 let h=hdr(P(m.n));
 if(pl.fin){const f=pl.fin;h+=`<h2>🎉 ${E(P(['బాగుంది! సెషన్ పూర్తి','Well done! Session complete']))}</h2><div class="c"><div class="p1 big">+${f.xp} XP · ⏱ ${m.min} ${TE()?'నిమి':'min'}</div><div class="p2">🔥 ${D.streak} · ⭐ ${level()} · 🏆 ${D.ch.length}/21</div>${f.badges.map(b=>`<div class="bdg"><span class="ic">${b.ic}</span><div>${B(b.n)}</div></div>`).join('')}</div><div class="row"><button class="b" data-a="quiz" data-v="${i}">❓ ${E(P(['క్విజ్ చేయండి','Take the quiz']))}</button>${i<19?`<button class="b or" data-a="lesson" data-v="${i+1}">${E(P(['తరువాత పాఠం','Next Lesson']))} →</button>`:''}<button class="b g" data-a="course">${E(P(['కోర్సు','Course']))}</button></div>`+foot();render(h,keep);return}
 const R=REDUCE();
 h+=`<h2>${m.ic} ${E(P(m.n))}</h2><div class="p2">${E(TE()?m.n[1]:m.n[0])}</div><div class="orbw"><svg viewBox="0 0 250 250"><circle cx="125" cy="125" r="116" fill="none" stroke="#ffffff22" stroke-width="8"/><circle id="mdring" cx="125" cy="125" r="116" fill="none" stroke="#22d3ee" stroke-width="8" stroke-linecap="round" stroke-dasharray="${2*Math.PI*116}" stroke-dashoffset="${2*Math.PI*116}" transform="rotate(-90 125 125)"/></svg><div class="orb" id="mdc" ${R?'style="transform:scale(.85)"':''}></div><div class="ol"><div id="mdl" class="p1 big"></div><div id="mdn" class="p2"></div></div></div>
 <div style="text-align:center"><b id="mdt" style="font-size:26px;color:#22d3ee">${mmss(m.sec)}</b> <span class="sm">/ ${mmss(m.sec)} · ${E(P(['మిగిలిన సమయం','time left']))}</span></div><div class="bar" style="margin:8px 0"><i id="mdp"></i></div>
 <div class="c seg" id="mdseg"></div>
 <div class="row" style="justify-content:center"><button class="b ok" data-a="pplay" id="mdbtn">▶ ${E(P(['ప్లే','Play']))}</button><button class="b g" data-a="ppause">⏸ ${E(P(['పాజ్','Pause']))}</button><button class="b g" data-a="pstop">⏹ ${E(P(['స్టాప్','Stop']))}</button></div>
 <div class="c"><h3>🔊 ${E(P(['వాయిస్','Voice']))}</h3>${sel('voice',[['auto',['ఆటో','Auto']],['te',['తెలుగు వాయిస్','Telugu voice']],['en',['ఇంగ్లీష్ వాయిస్','English voice']],['off',['ఆఫ్','Off']]])}<div class="sm" id="mdnv"></div><h3>🌿 ${E(P(['నేపథ్య ధ్వని','Background sound']))}</h3>${sel('bg',[['off',['ఆఫ్','Off']],['rain',['వాన','Rain']],['ocean',['సముద్రం','Ocean']],['wind',['గాలి','Wind']]])}<h3>🔉 ${E(P(['వాల్యూమ్','Volume']))}</h3><input type="range" min="0" max="1" step="0.05" value="${D.vol}" data-a="vol" id="mdvol" aria-label="Volume"></div>
 <div class="c"><b>${E(P(['ఈ సెషన్ గురించి','About this session']))}</b>${B(m.i)}<div class="sm">${E(P(['శ్వాస: పీల్చు 4 సె · ఆగు 2 సె · వదులు 6 సె','Breathing: in 4s · hold 2s · out 6s']))}</div></div>`+(m.care?care():'')+foot();
 render(h,keep);pupd(true)}
function pupd(force){if(!pl||pl.fin)return;const m=MODS[pl.i],t=pl.t,left=m.sec-t,c=document.getElementById('mdc');if(!c)return;
 const cyc=t%12,R=REDUCE();let lab,n;if(cyc<4){lab=['పీల్చండి','Breathe In'];n=4-cyc}else if(cyc<6){lab=['ఆపండి','Hold'];n=6-cyc}else{lab=['వదలండి','Breathe Out'];n=12-cyc}
 const started=pl.run||t>0;document.getElementById('mdl').textContent=started?P(lab):P(['సిద్ధమా?','Ready?']);document.getElementById('mdn').textContent=started?(TE()?lab[1]:lab[0])+' '+n+'s':P(['ప్లే నొక్కండి','Press Play']);
 document.getElementById('mdt').textContent=mmss(left);document.getElementById('mdp').style.width=(t*100/m.sec)+'%';const rg=document.getElementById('mdring');if(rg){const C=2*Math.PI*116;rg.style.strokeDashoffset=C*(1-t/m.sec)}
 if(!R&&started&&(pl.run||force)){if(cyc===0||force&&cyc<4){c.style.transition='transform '+(cyc===0?4:4-cyc)+'s ease-in-out';c.style.transform='scale(1)'}else if(cyc===6||force&&cyc>=6){c.style.transition='transform '+(cyc===6?6:12-cyc)+'s ease-in-out';c.style.transform='scale(.6)'}}
 const k=segAt(m,Math.min(t,m.sec-1)),sg=m.seg[k],box=document.getElementById('mdseg');if(box)box.innerHTML=B([sg[0],sg[1]],1)+`<div class="sm">${k+1}/${m.seg.length}</div>`;
 const nv=document.getElementById('mdnv');if(nv)nv.textContent=noVoiceNote()?P(['ఈ ఫోన్‌లో ఈ భాష వాయిస్ లేదు. టెక్స్ట్ చూడండి లేదా మరో వాయిస్ ఎంచుకోండి.','No voice for this language on this phone. Read the text or pick another voice.']):'';
 if(pl.run&&k!==pl.seg){pl.seg=k;speak(vlang()==='te'?sg[0]:sg[1])}}
function pplay(){if(!pl||pl.fin)return;if(pl.run)return;ctx();if(pl.t===0)chime();pl.run=true;bgStart();pl.seg=-1;const m=MODS[pl.i];pl.tm=setInterval(()=>{pl.t++;if(pl.t>=m.sec){pupd();pfinish();return}pupd()},1000);pupd(true);const b=document.getElementById('mdbtn');if(b)b.textContent='▶ '+P(['కొనసాగించు','Resume'])}
function ppause(){if(!pl||!pl.run)return;clearInterval(pl.tm);pl.tm=null;pl.run=false;try{speechSynthesis.cancel()}catch(e){}try{if(ac)ac.suspend()}catch(e){}bgStop()}
function pstop(){if(!pl)return;stopPl();pl={i:pl.i,t:0,run:false,seg:-1,fin:null};draw(false)}
function pfinish(){const m=MODS[pl.i];stopPl();chime();const before=BADGES.filter(b=>b.ok()).map(b=>b.id);const first=!D.done[m.id];const xp=first?30:10;D.done[m.id]=today();D.xp+=xp;D.mins=Math.round((D.mins+m.sec/60)*10)/10;const d=today();D.daily[d]=(D.daily[d]||0)+m.sec/60;D.week[wkey()]=(D.week[wkey()]||0)+m.sec/60;
 if(D.last!==d){D.streak=D.last===yday()?D.streak+1:1;D.last=d}if(D.ch.indexOf(d)<0&&D.ch.length<21){D.ch.push(d);D.xp+=5}save();
 const nb=BADGES.filter(b=>b.ok()&&before.indexOf(b.id)<0);pl.fin={xp,badges:nb};draw(true)}
// ---- quiz ----
function scQuiz(i){const m=MODS[i];if(!qz||qz.i!==i||qz.over){qz={i,n:0,right:0,sel:null,over:false}}const q=m.Q[qz.n];
 let h=hdr(P(m.n))+`<h2>❓ ${E(P(['క్విజ్','Quiz']))} ${qz.n+1}/${m.Q.length}</h2><div class="bar"><i style="width:${qz.n*100/m.Q.length}%"></i></div><div class="c">${q.k==='s'?`<span class="chip">${E(P(['సందర్భం','Scenario']))}</span>`:q.tag==='x'?`<span class="chip">${E(P(['జతపరచండి','Match the concept']))}</span>`:q.k==='t'?`<span class="chip">${E(P(['నిజమా? కాదా?','True or false']))}</span>`:''}${B(q.t,1)}</div>`;
 q.o.forEach((o,k)=>{let cl='';if(qz.sel!=null){cl=k===q.a?'right':k===qz.sel?'wrong':''}h+=`<button class="opt ${cl}" data-a="ans" data-v="${k}" ${qz.sel!=null?'disabled':''}>${B(o)}</button>`});
 if(qz.sel!=null){const ok=qz.sel===q.a;h+=`<div class="c ${ok?'':'warn'}"><b>${ok?'✅ '+E(P(['సరైనది!','Correct!'])):'❌ '+E(P(['సరైన సమాధానం పైన చూడండి','See the correct answer above']))}</b>${B(q.ex)}</div><button class="b" data-a="qnext">${qz.n+1<m.Q.length?E(P(['తరువాత','Next'])):E(P(['ఫలితం','Result']))} →</button>`}
 render(h+foot())}
function scQres(i){const m=MODS[i],pc=Math.round(qz.right*100/m.Q.length);let h=hdr(P(m.n))+`<h2>🏁 ${E(P(['క్విజ్ ఫలితం','Quiz result']))}</h2><div class="c"><div class="p1 big">${qz.right}/${m.Q.length} · ${pc}%</div><div class="p2">+${qz.gain} XP</div><div class="p1">${E(P(pc>=100?['అద్భుతం! 🌟','Excellent! 🌟']:pc>=50?['బాగుంది! 👍','Good job! 👍']:['మళ్ళీ ప్రయత్నించండి, నేర్చుకోవడమే ముఖ్యం.','Try again. Learning is what matters.']))}</div></div><div class="row"><button class="b g" data-a="quizagain" data-v="${i}">↻ ${E(P(['మళ్ళీ','Retry']))}</button>${i<19?`<button class="b or" data-a="lesson" data-v="${i+1}">${E(P(['తరువాత పాఠం','Next Lesson']))} →</button>`:''}<button class="b g" data-a="course">${E(P(['కోర్సు','Course']))}</button></div>`+foot();render(h)}
function qans(k){if(qz.sel!=null)return;const m=MODS[qz.i],q=m.Q[qz.n];qz.sel=k;if(k===q.a){qz.right++;D.xp+=10;save()}draw(false)}
function qnext(){const m=MODS[qz.i];qz.sel=null;qz.n++;if(qz.n>=m.Q.length){const first=D.quiz[m.id]==null;qz.gain=qz.right*10+(first?10:0);if(first)D.xp+=10;D.quiz[m.id]=Math.max(D.quiz[m.id]||0,Math.round(qz.right*100/m.Q.length));qz.over=true;save();stk[stk.length-1]={s:'qres',a:qz.i};draw(true)}else draw(true)}
