function scProg(a,keep){let h=hdr(P(['నా పురోగతి','My Progress']))+`<h2>📊 ${E(P(['నా పురోగతి','My Progress']))}</h2><div class="grid3"><div class="st"><b>${D.xp}</b><span>XP</span></div><div class="st"><b>⭐ ${level()}</b><span>${E(P(['స్థాయి','Level']))}</span></div><div class="st"><b>🔥 ${D.streak}</b><span>${E(P(['వరుస','Streak']))}</span></div><div class="st"><b>${Math.round(D.mins*10)/10}</b><span>${E(P(['నిమిషాలు','Minutes']))}</span></div><div class="st"><b>${doneCount()}/20</b><span>${E(P(['పాఠాలు','Lessons']))}</span></div><div class="st"><b>${overall()}%</b><span>${E(P(['మొత్తం','Overall']))}</span></div></div>
 <div class="c"><b>${E(P(['స్థాయి పురోగతి','Level progress']))}</b><div class="bar" style="margin:6px 0"><i style="width:${D.xp%100}%"></i></div><div class="sm">${D.xp%100}/100 XP</div><b>🎯 ${E(P(['రోజువారీ లక్ష్యం','Daily goal']))}: ${dailyMin()}/${DAILY_GOAL} ${TE()?'నిమి':'min'}</b><div class="bar" style="margin:6px 0"><i style="width:${Math.min(100,dailyMin()*100/DAILY_GOAL)}%"></i></div><b>📅 ${E(P(['వారపు లక్ష్యం','Weekly goal']))}: ${weekMin()}/${WEEK_GOAL} ${TE()?'నిమి':'min'}</b><div class="bar" style="margin:6px 0"><i style="width:${Math.min(100,weekMin()*100/WEEK_GOAL)}%"></i></div></div><h3>🏅 ${E(P(['బ్యాడ్జ్‌లు','Badges']))}</h3>`;
 BADGES.forEach(b=>{const ok=b.ok();h+=`<div class="bdg ${ok?'':'off'}"><span class="ic">${b.ic}</span><div style="flex:1">${B(b.n)}<div class="sm">${E(P(b.d))}</div></div><span>${ok?'✅':'🔒'}</span></div>`});
 h+=`<h3>📘 ${E(P(['పాఠాల స్థితి','Lesson status']))}</h3>`+MODS.map(m=>`<div class="row" style="justify-content:space-between;border-bottom:1px solid #ffffff14;padding:5px 0"><span>${m.no}. ${E(P(m.n))}</span><span>${modPct(m)}%</span></div>`).join('')+'<p class="sm">'+E(P(['పురోగతి ఈ ఫోన్‌లో మాత్రమే ఉంటుంది.','Progress is stored only on this phone.']))+'</p>'+foot();render(h,keep)}
function scCh(a,keep){const n=D.ch.length,td=D.ch.indexOf(today())>=0;let h=hdr(P(['21 రోజుల ఛాలెంజ్','21-Day Challenge']))+`<h2>🏆 ${E(P(['21 రోజుల ఛాలెంజ్','21-Day Challenge']))}</h2><div class="p2">${E(TE()?'21-Day Challenge':'21 రోజుల ఛాలెంజ్')}</div>`+DG.timeline()+`<div class="c"><div class="p1 big">${n}/21 ${TE()?'రోజులు':'days'}</div><div class="bar" style="margin:6px 0"><i style="width:${n*100/21}%"></i></div>${B(['రోజుకు ఒక సెషన్ పూర్తి చేస్తే ఒక రోజు లెక్కలోకి వస్తుంది.','Finish one session a day and that day counts.'])}</div><div class="grid3" style="grid-template-columns:repeat(7,1fr)">`;
 for(let k=0;k<21;k++)h+=`<div class="cell ${k<n?'dn':k===n&&!td?'td':''}">${k<n?'✓':k+1}</div>`;
 const tm=MODS[todayMod()];h+=`</div><div class="c"><h3>${E(P(['నేటి సెషన్','Today\u2019s session']))}</h3>${td?B(['ఈ రోజు పూర్తయింది! రేపు కలుద్దాం.','Done for today! See you tomorrow.']):B(tm.n,1)}<button class="b ok" data-a="play" data-v="${tm.no-1}">▶ ${E(P(['మొదలుపెట్టు','Start']))}</button></div>`+(n>=21?`<div class="c" style="border-color:#22c55e"><div class="p1 big">🏆 ${E(P(['21 రోజుల ఛాంపియన్!','21-Day Champion!']))}</div></div>`:'')+`<div class="c"><h3>${E(P(['21 రోజుల ప్రణాళిక','21-day plan']))}</h3>`+PLAN.map((p,k)=>`<div class="row" style="border-bottom:1px solid #ffffff14;padding:4px 0"><b style="width:46px">${TE()?'రోజు':'Day'} ${k+1}</b><span style="flex:1">${E(P(MODS[p-1].n))}</span><span>${k<n?'✅':''}</span></div>`).join('')+'</div>'+foot();render(h,keep)}
function scMap(a,keep){const cx=180,cy=170,r=118;let s='';MAP.forEach((m,k)=>{const an=(k/8)*2*Math.PI-Math.PI/2,x=cx+r*Math.cos(an)*1.35,y=cy+r*Math.sin(an);const sel=k===mmSel;s+=`<g class="mmn" data-a="mm" data-v="${k}"><line x1="${cx}" y1="${cy}" x2="${x}" y2="${y}" stroke="${sel?'#fb923c':'#22d3ee'}" stroke-width="2.5" stroke-dasharray="200" stroke-dashoffset="200"><animate attributeName="stroke-dashoffset" from="200" to="0" dur="1.2s" fill="freeze"/></line><circle cx="${x}" cy="${y}" r="${sel?29:25}" fill="${sel?'#7c2d12':'#1e2a78'}" stroke="${sel?'#fb923c':'#22d3ee'}" stroke-width="2"/><text x="${x}" y="${y-2}" text-anchor="middle" fill="#fff" font-size="9" font-weight="700">${E(m[1].split(' ')[0])}</text><text x="${x}" y="${y+9}" text-anchor="middle" fill="#9fd8ff" font-size="8">${E(m[0].length>9?m[0].slice(0,9)+'…':m[0])}</text></g>`});
 const f=(sel)=>sel;let h=hdr(P(['మైండ్ మ్యాప్','Mind Map']))+`<h2>🧩 ${E(P(['ధ్యానం మైండ్ మ్యాప్','Meditation Mind Map']))}</h2><div class="p2">${E(P(['ఒక శాఖను తాకండి','Tap a branch']))}</div><div class="c"><svg viewBox="-20 0 400 340" style="width:100%;height:auto"><defs><radialGradient id="mg"><stop offset="0" stop-color="#a78bfa"/><stop offset="1" stop-color="#4f46e5"/></radialGradient></defs>${s}<circle cx="${cx}" cy="${cy}" r="42" fill="url(#mg)" stroke="#fff" stroke-width="2"><animate attributeName="r" values="40;45;40" dur="4s" repeatCount="indefinite"/></circle><text x="${cx}" y="${cy-2}" text-anchor="middle" fill="#fff" font-size="11" font-weight="800">MEDITATION</text><text x="${cx}" y="${cy+12}" text-anchor="middle" fill="#e0e7ff" font-size="11">ధ్యానం</text></svg></div>`;
 h+=mmSel>=0?`<div class="c" style="border-color:#fb923c88"><h3>${MAP[mmSel][1]} · ${MAP[mmSel][0]}</h3>${B([MAP[mmSel][2],MAP[mmSel][3]])}</div>`:`<div class="c">${B(['ఒక శాఖను తాకి వివరణ చదవండి.','Tap a branch to read its explanation.'])}</div>`;
 h+=`<div class="row">`+MAP.map((m,k)=>`<button class="b g sm" data-a="mm" data-v="${k}">${E(P([m[0],m[1]]))}</button>`).join('')+'</div>'+foot();render(h,keep)}
